"""p-82af68dd@100000 layers.15.mlp.down_proj:3521: an "anticipating 'or'" feature.

What it does: this component writes a direction that raises the next-token logit for
" or" (and its translations: 或, или, hoặc, eller, أو). So it is strongest where the model
expects an alternative to come next: right after "either", inside an "either ... or" or
"whether ... or" construction, on a word that closes the first option of a choice
("mistake", "typo", "injury", ...), and in documents that already use " or" a lot.

The program adds these cues, each a small readable rule. It captures only a little of
the activation's variance: the large spikes depend on the model's own sense that " or"
is coming next, which a rule over the prefix cannot see.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

# Words that often close the first option of a choice ("mistake or omission").
FAULT_WORDS = {
    "typo", "mistake", "misunderstanding", "negligence", "malfunction",
    "termination", "injury", "incurred",
}
SPAN_MAX = 12  # an open either/whether span lasts at most this many tokens
OR_CAP = 6  # " or" uses in a document, counted up to this many


def step(carry, prefix, upstream: Mapping):
    word = prefix.token_strings[-1].strip().lower()
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "span": None, "ors": 0}
    span, ors = carry["span"], carry["ors"]

    if word == "either":
        value = 5.5
    elif word == "whether":
        value = 1.5
    elif word in FAULT_WORDS:
        value = 2.5
    elif span is not None:
        value = 1.5  # inside an open either/whether ... or
    else:
        value = 0.0
    value += 0.05 * min(ors, OR_CAP)  # documents that use " or" a lot

    # Update the memory with this token, for the positions after it.
    if word == "or":
        span, ors = None, ors + 1
    elif word in ("either", "whether"):
        span = 0
    elif span is not None:
        span = span + 1 if span < SPAN_MAX else None
    return {"doc": doc, "span": span, "ors": ors}, float(value)

"""A "by" detector for layers.15.mlp.down_proj component 3522.

The component is nearly silent on most tokens, but its activation is large and
positive on the English preposition "by" when it introduces an agent or a means or
a deadline: "was established by a grant", "completed by May", "by clicking here",
"by default", "by the time". It is weaker on "by" in arithmetic ("divided by",
"multiplied by", which give about 0) and in credit lines ("Posted by", "Created by"),
and it is weakly positive on the Spanish and French "by" words "por" and "par".

This program predicts that: about 1.4 on "by", 0 after arithmetic words, 0.2 after
credit words, 0.7 on " por" / " par", and 0 on every other token. Most other tokens
carry small activations (typically within +-0.3) with no simple pattern, so they are
predicted as 0.
"""

READS = ()

MATH_WORDS = {"divided", "multiplied", "divisible", "multiply", "divide"}
CREDIT_WORDS = {"posted", "created"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1]
    bare = word.strip().lower()
    prev = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower()
    if bare == "by":
        if prev in MATH_WORDS:
            value = 0.0
        elif prev in CREDIT_WORDS:
            value = 0.2
        else:
            value = 1.4
    elif word.startswith(" ") and bare in ("por", "par"):
        value = 0.7
    else:
        value = 0.0
    return carry, value

"""Arrival detector for MLP neuron 3532 of layer 15 (Qwen3-1.7B).

The component is one hidden unit of the layer-15 MLP. Its output pushes the next-word
prediction toward "incoming", "input", "coming", "from" and "influx". So it is active where
the text is about something coming in or being received from outside:
  - the arrival word itself: strongest for "incoming", "inbound", "influx", "donations",
    "spam", "threat" and their Chinese or Japanese equivalents, then "came", "received",
    "arrives", "signal", "supply", and weaker for "call", "mail", "flow", "source";
  - the "of", "from" or "in" right after such a word ("an influx of", "a call from").
Elsewhere it sits near zero. The word lists are the whole model: no context beyond the
previous word is used, and the many small unexplained fluctuations are left out.
"""
from collections.abc import Mapping

READS: tuple[str, ...] = ()

STRONG = {
    "incoming", "inbound", "influx", "donations", "donation", "spam", "threat", "threats",
    "immigrants", "来电", "收到", "接到", "捐赠", "移民", "突然", "供应",
}
MEDIUM = {
    "arrive", "arrived", "arrives", "arriving", "arrival", "came", "come", "comes", "coming",
    "received", "receive", "receiving", "receives", "receipt", "signal", "signals",
    "input", "inputs", "feedback", "sudden", "suddenly", "unexpected", "supplied", "supply",
    "supplies", "funding", "revenue", "traffic", "attack", "attacks", "immigration",
    "来", "来自", "来的", "來自", "來", "影响", "gift", "gifts", "contribution", "contributions",
}
WEAK = {
    "call", "calls", "mail", "email", "message", "messages", "letter", "news", "send", "sent",
    "flow", "flows", "source", "sources", "stream", "force", "forces", "impact", "pressure",
    "influence", "income", "demand", "surge", "flood", "wave", "rush", "offers", "funds",
    "visitors", "visit", "notice", "入",
}
PREPS = {"of", "from", "in", "から", "的"}
CONCEPT = STRONG | MEDIUM | WEAK


def step(carry, prefix, upstream: Mapping):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if word in STRONG:
        value = 6.0
    elif word in MEDIUM:
        value = 2.5
    elif word in WEAK:
        value = 1.0
    elif word in PREPS and before in CONCEPT:
        value = 2.0
    elif word in PREPS:
        value = 0.4
    else:
        value = 0.05
    return carry, float(value)

"""Inequality wording: strict bounds ("less than", "greater than", "<", ">")
push this component's activation up; inclusive bounds ("<=", ">=", "≤", "≥",
"or equal", "no less than", "not more than", "at least") push it down.

Found by reading the top and bottom activations: the strongest positive values
are on strict comparison signs and on "than" after less/greater; the strongest
negative values are on non-strict signs and on "than" after "or equal" or a
negation. Everything else is predicted as 0 (the component's diffuse,
mostly digit-driven noise is not modelled).
"""

import re

READS = ()

INCLUSIVE_SIGNS = {"≤", "≥", "<=", ">="}
STRICT_WORDS = {"less", "greater", "fewer", "smaller", "larger", "bigger"}
INCLUSIVE_WORDS = {"equal", "or", "least", "most", "not", "no", "at"}


def step(carry, prefix, upstream):
    # The current token and the up-to-three tokens before it.
    tokens = [s.strip() for s in prefix.token_strings[-4:]]
    cur, before = tokens[-1], tokens[:-1]
    prev = before[-1] if before else ""
    if cur in INCLUSIVE_SIGNS:
        return None, -10.0
    if cur in ("<", ">"):
        # A strict sign after a math operand (variable, digit, ")") is strongest.
        return None, 6.0 if re.fullmatch(r"[A-Za-z0-9)]", prev) else 1.0
    if cur == "than":
        if any(w in INCLUSIVE_WORDS for w in before):
            return None, -10.0
        if prev in STRICT_WORDS:
            return None, 7.0
    return None, 0.0

"""Start-of-document number detector, for layer 15 MLP hidden unit 3544 (via its down_proj column).

In plain terms: this component's activation is almost entirely one MLP neuron of
layer 15 (about 1.3 times it). Away from the start of a document it is small,
diffuse noise (rms about 0.5) that no simple rule captures. Right at the start of a
document, though, it swings strongly negative when a number begins: on the second
token, a digit is strongly negative, most of all when the document's first token
is a bare space (a document that opens " 1..."); on the third token, a digit is
moderately negative. This program predicts those early values and 0 elsewhere.
"""

READS = ()


def is_digit(s):
    return s != "" and s.strip().isdigit()


def is_space(s):
    return s != "" and s.strip() == "" and "\n" not in s and "\r" not in s


def is_word(s):
    return s != "" and s.strip().isalpha()


def step(carry, prefix, upstream):
    # Position within the current document: restart the count when the document changes.
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pos = 0
    else:
        pos = carry[1] + 1
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    value = 0.0
    if pos == 1:  # second token of the document
        if is_digit(tok):
            value = -25.0 if is_space(prev) else -7.0
        elif is_word(tok):
            value = -0.5
        else:
            value = -1.0
    elif pos == 2 and is_digit(tok):  # third token of the document
        value = -4.0
    return (doc, pos), value

"""Opening quotation marks (and opening math dollars).

Component p-82af68dd@100000/layers.15.mlp.down_proj:3563 writes a large positive
value on the token that OPENS a quoted span: a quotation in prose, or a string
literal in code. Closing quotes (`",`, `":`, `".`), apostrophe contractions
(`'s`, `'t`) and ordinary words stay near zero. Strength depends on the kind of
opener and on the token just before it:

- curly quotes “ „ « 「 《 ‘ are strongest (about 13), straight double
  quotes ` "` and single quotes ` '` are about 9 to 10, backticks about 7;
- a bare word-start quote like `"The` at the start of a line is about 20;
- opening math dollars (` $\\`, ` $$`) are about 10, and a plain currency ` $`
  about 4;
- after a closing JSON quote or a line start the value is lower, after a colon,
  comma, `=` or bracket in running text it is higher;
- the first token of a document has no context, and stays at zero.

The program is a rule-based detector, not a table of token ids: it finds the
opener by its shape, then scales it by kind and context.
"""

READS = ()

CURLY_OPEN = set("“„«「《‘")
VALUE = {"curly": 13.0, "straight": 9.3, "single": 10.1, "backtick": 6.7,
         "word": 20.0, "math": 10.0, "dollar": 4.0}
BEFORE = {"json": 0.7, "linestart": 0.85, "punct": 1.3, "word": 1.0}


def _opener_kind(token):
    """The kind of quotation or math opener this token is, or None."""
    core = token.lstrip(" ([{=\\")
    lead = token[: len(token) - len(core)]
    if not core:
        return None
    first, rest = core[0], core[1:]
    if first in CURLY_OPEN:
        return "curly"
    if token[-1:] in CURLY_OPEN and not any(ch.isalpha() for ch in token):
        return "curly"  # punctuation then an opener, as in "：“"
    if first == "$":
        return "math" if rest[:1] in ("\\", "$", "(") else "dollar"
    if first == "`":
        if rest.startswith("`"):
            return "backtick"  # code fence
        return "backtick" if lead or not rest else None
    if first == '"':
        if lead:  # ' "', '("', ' \"': starts a span; '",' and '":' close one
            return None if rest[:1] in (".", ",", ";", ":", ")", "]", "}", "\n", ">") else "straight"
        return "word" if rest[:1].isalnum() else None  # '"The' opening a line
    if first == "'":
        return "single" if lead else None  # " 'x" opens; "'s" is a contraction
    return None


def _before_kind(prefix):
    """What the token before the current one is like."""
    prev = prefix.token_strings[-2]
    if prev in ('":', '",', '"'):
        return "json"
    if prev.strip() == "" or prev.endswith("\n"):
        return "linestart"
    if prev in (":", ",", "=", " =", "(", "[", "{", "."):
        return "punct"
    return "word"


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    kind = _opener_kind(token)
    first_of_document = len(prefix.document_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]
    if kind is None or first_of_document:
        return carry, 0.0
    return carry, VALUE[kind] * BEFORE[_before_kind(prefix)]

"""Layer 15 MLP hidden unit 3565, the component's one input direction.

Its activation is that unit's value. It is largest on words that open a post-modifier:
relative pronouns "that", "which", "where" (strongest after a comma, as in ", which ..."),
and past participles right after a noun ("guidelines set by", "requirements specified in").
It is negative on "who", "whom", "whose" and on the perfect auxiliaries "has", "had", "have".
Its sign is only partly predictable from the word, so the program predicts each class's
average value and 0 elsewhere. That captures about 1-2% of its variance.
"""

import wordnet

READS = ()

RELATIVE = {" that", " which", " where"}
WHO = {" who", " whom", " whose"}
PERFECT_AUX = {" has", " had", " have"}
IRREGULAR_PARTICIPLES = {
    "set", "made", "given", "found", "known", "built", "held", "shown", "taken",
    "written", "done", "seen", "used", "based", "born", "filed", "granted",
}


def is_participle(word):
    """A past participle by spelling: a lowercase word ending in -ed, or a listed irregular."""
    w = word.strip()
    return (len(w) > 4 and w.endswith("ed") and w[0].islower()) or w in IRREGULAR_PARTICIPLES


def is_noun(word):
    senses = wordnet.parts_of_speech(word.strip().lower())
    return "noun" in senses and "verb" not in senses


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1]
    before = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ","
    if word in RELATIVE:
        value = 1.5 if before == "," else 0.6
    elif word in WHO:
        value = -1.2
    elif word in PERFECT_AUX:
        value = -0.3
    elif is_participle(word):
        value = 0.75 if is_noun(before) else 0.25
    else:
        value = 0.0
    return carry, value

"""Predicts layers.15.mlp.down_proj:3572 from the words it sits on.

This component is a dense readout of layer 15's MLP hidden state: its activation is one
linear projection spread thinly over thousands of hidden units. Most of its variance is
context-driven and no simple rule captures it. The part that tracks words is coordination:
a conjunction that joins two phrases ("the state and federal level", "Hall of Fame and")
pushes it clearly negative, while the same word right after a comma (", and") stays near 0.
"or" and "but" push it positive. Chat/document control tokens get a fixed value.
Everything else is predicted as 0.
"""
from collections.abc import Mapping

READS: tuple[str, ...] = ()

# Coordinating conjunctions joining phrases (English, German, French, Russian).
CONJUNCTIONS = {" and", " And", " und", " et", " и"}
# Disjunction and contrast.
OR_BUT = {" or": 0.6, " but": 0.5}
# End-of-text and tool-call control tokens; </think> is the one positive case.
CONTROL = {"<|endoftext|>": -0.9, "<tool_call>": -0.9, "<tool_response>": -1.0, "</think>": 1.3}


def step(carry, prefix, upstream: Mapping):
    tok = prefix.token_strings[-1]
    same_doc = len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    if tok in CONJUNCTIONS:
        return carry, (-0.1 if prev == "," else -0.9)
    if tok in OR_BUT:
        return carry, OR_BUT[tok]
    return carry, CONTROL.get(tok, 0.0)

"""Code-indentation guess for one MLP down-projection component (layer 15, unit 3575).

This component is weak and diffuse: most of its variance is not explained by any
simple rule. Its clearest pattern is in source code. It rises on the indentation
that starts a line stepping deeper into a block (an `if` body, a loop, a `case`),
and on statement words such as `return`, `echo`, `push`, `append` while the text
looks like code. Structured-data punctuation (`":`, `{"`, `==`) dips a little, and
other tokens sit near the component's average of about -0.03.
"""

READS = ()

STATEMENT_WORDS = {"return", "echo", "push", "append", "console", "cout", "throw", "print"}
DATA_TOKENS = {'":', '{"', "':", '",', '":', "=>", "=="}
CODE_CHARS = set("{};=()[]<>\t")


def width(s):
    """Indentation width in spaces, with a tab as 4 spaces."""
    return len(s.expandtabs(4))


def step(carry, prefix, upstream):
    # carry: (indent of previous line, indent of this line, at line start, code density)
    if carry is None or prefix.document_ids[-1] != prefix.document_ids[-2]:
        carry = (0, 0, True, 0.0)
    prev_w, cur_w, at_start, dens = carry
    s = prefix.token_strings[-1]
    # code density: a decaying share of recent tokens that carry code punctuation or newlines
    codey = any(c in CODE_CHARS for c in s) or "\\n" in s or "\n" in s
    dens = 0.9 * dens + 0.1 * codey
    if "\n" in s or "\\n" in s:
        return (cur_w, 0, True, dens), 0.0
    if s and s.strip(" \t") == "":
        if at_start:
            w = width(s)
            if w > prev_w:
                value = 0.7  # stepping deeper into a block
            elif w == prev_w:
                value = 0.0
            else:
                value = -0.5  # stepping back out
            return (prev_w, w, False, dens), value * (0.5 + dens)
        return (prev_w, cur_w, False, dens), 0.08
    word = s.strip()
    if word in STATEMENT_WORDS:
        value = 2.5 * dens
    elif word in DATA_TOKENS:
        value = -0.15
    else:
        value = -0.04
    return (prev_w, cur_w, False, dens), value

"""Layer 15 MLP down_proj, component 3578: a weak, mostly lexical trace.

What the component does: when it is negative, it adds to the residual stream a
direction that raises the logits of "these / their / them" words (its output
direction, projected onto the embedding, does this). Its activation is diffuse:
no token identity explains more than about 1% of its variance, and it barely
changes the model's next-token predictions when switched off.

What this program predicts, from the current token alone:
- words that point back at a group or close a list ("these", "etc", "等", "など",
  "(s", "others") are strongly negative;
- coordinators that join two things ("and", "or", "both", "et") are mildly positive;
- closing brackets are slightly negative;
- every other token is 0.
"""

READS = ()

GROUP_REFERENCES = {
    " these", " These", "These", "these", " others", " such",
    " etc", "等", "など", "などの", "とか", "国内外", "(s",
}
COORDINATORS = {" and", " or", " both", " et", "/or", " and/or"}
CLOSING_BRACKETS = {")", "）"}

GROUP_VALUE = -0.47  # mean activation on group-reference tokens
COORDINATOR_VALUE = 0.14  # mean activation on coordinators
BRACKET_VALUE = -0.17  # mean activation on closing brackets


def predict(token):
    """The component's activation for one token, read from that token alone."""
    if token in GROUP_REFERENCES:
        return GROUP_VALUE
    if token in COORDINATORS:
        return COORDINATOR_VALUE
    if token in CLOSING_BRACKETS:
        return BRACKET_VALUE
    return 0.0


def step(carry, prefix, upstream):
    return carry, predict(prefix.token_strings[-1])


if __name__ == "__main__":
    for token in [" these", " and", ")", " the", "等"]:
        print(repr(token), predict(token))
